import XCTest
import AppKit
import PDFKit
@testable import KongFolio

final class Release048Tests: XCTestCase {
    func folder() throws -> URL { try Release027Tests().folder() }
    func testToolbarDefaultStartsWithNewFiles() { XCTAssertEqual(Array(ReaderToolbarProfile().actions.prefix(5)),[.newPDF,.newMarkdown,.newText,.newHTML,.open]);XCTAssertEqual(SingleRowToolbarPolicy.titleWidth(1200),0) }
    func testToolbarBudgetAndOverflowNeverLoseTools() { let p = ReaderToolbarProfile();for w in stride(from:320.0,through:1600,by:10) { XCTAssertEqual(Set(p.visible(width:w)+p.hidden(width:w)),Set(FileToolbarAction.allCases));XCTAssertTrue(Double(p.visible(width:w).count)*36+102<=w) } }
    func testToolbarUnknownAndDuplicatePreferencesAreRepaired() { var p = ReaderToolbarProfile();p.order = ["bad","open","open"];XCTAssertEqual(p.actions.count,FileToolbarAction.allCases.count);XCTAssertEqual(p.actions.first,.open) }
    func testToolbarPinsAndOrderSurvivePreferencesReload() { let d = UserDefaults(suiteName:UUID().uuidString)!;var p = ReaderToolbarProfile();p.pinned = ["library"];p.move(.library,by:-1);p.save(d);let q = ReaderToolbarProfile.load(d);XCTAssertEqual(p,q);XCTAssertEqual(q.visible(width:320).first,.library) }
    @MainActor func testCleanEditingRoundTripKeepsImagesAndCorrections() {
        let c = EditorCorrection(original:"□",replacement:"文",kind:"补字",reason:"据原本"),source = "正文😀\n\n![图](file:///tmp/image.png)\n\n"+c.marker+"\n末尾",s = CleanWritingSession();s.load(source)
        XCTAssertEqual(s.blocks.map{$0.source+$0.suffix}.joined(),source);let text = s.blocks.first{$0.kind == .text}!;let edited = s.edit(text.id,text:"改后的正文😀")
        XCTAssertTrue(edited.contains("file:///tmp/image.png"));XCTAssertTrue(edited.contains(c.marker));XCTAssertEqual(s.blocks.first?.id,text.id)
    }
    @MainActor func testCleanSessionKeepsParagraphIdentityAfterImageRebase() { let s = CleanWritingSession();s.load("正文\n\n![图](old.png)\n\n结尾");let id = s.blocks.first!.id;s.page = 2;s.load("正文\n\n![图](new.png)\n\n结尾");XCTAssertEqual(s.blocks.first!.id,id);XCTAssertEqual(s.page,2) }
    @MainActor func testCleanMetadataCannotBeEditedAsText() { let s = CleanWritingSession();s.load("![图](x.png)");let before = s.source;XCTAssertEqual(s.edit(s.blocks[0].id,text:"意外覆盖"),before) }
    @MainActor func testCitationSyncKeepsPersonalEssayTextAndSupportsUndo() throws {
        let j = ReadingJournal(storage:try folder());var r = ReadingRecord(kind:.excerpt,quote:"旧摘录");j.add(r);let e = j.newEssay(title:"札记");let block = j.insert(r,in:e);j.editEssay(e) { $0.blocks[$0.blocks.firstIndex{$0.id==block}!].text = "我的论述" };j.editRecord(r.id) { $0.quote = "校订后摘录" }
        let update = try XCTUnwrap(j.citationUpdates(e).first);try j.synchronizeCitation(update);let b = j.essay(e)!.blocks.first{$0.id == block}!;XCTAssertEqual(b.text,"我的论述");XCTAssertEqual(b.record?.quote,"校订后摘录");try j.undoBulk();XCTAssertEqual(j.essay(e)!.blocks.first{$0.id == block}?.record?.quote,"旧摘录")
        r.quote = "其他";XCTAssertTrue(ReadingCitationUpdate.changed(r,update.current))
    }
    @MainActor func testStaleCitationComparisonStops() throws { let j = ReadingJournal(storage:try folder()),r = ReadingRecord(kind:.excerpt,quote:"甲");j.add(r);let e = j.newEssay(title:"札记");j.insert(r,in:e);j.editRecord(r.id){$0.quote="乙"};let change = try XCTUnwrap(j.citationUpdates(e).first);j.editRecord(r.id){$0.quote="丙"};XCTAssertThrowsError(try j.synchronizeCitation(change)) }
    @MainActor func testBulkDeleteUndoAndNewEditProtection() throws { let j = ReadingJournal(storage:try folder()),r = ReadingRecord(kind:.note,note:"笔记");j.add(r);j.setRemoved([.record(r.id)],removed:true);XCTAssertTrue(j.canUndoBulk);try j.undoBulk();XCTAssertNil(j.record(r.id)?.removed);j.organize([.record(r.id)],tags:"甲",topic:"专题");j.editRecord(r.id){$0.note="新编辑"};XCTAssertThrowsError(try j.undoBulk());XCTAssertEqual(j.record(r.id)?.note,"新编辑") }
    func testSearchUsesUTF16AndBoundsMatches() { let hits = ReadingTextSearch.hits("😀文献 甲文献",query:"文献",identity:"note:x");XCTAssertEqual(hits.count,2);XCTAssertEqual(hits.first?.range.location,2);XCTAssertEqual(ReadingTextSearch.hits(String(repeating:"a",count:1000),query:"a",identity:"x").count,200) }
    func testSearchCoversEssayParagraphsAndCarriesStaleGuard() { let b = ReadingEssay.Block(text:"正文含研究关键词"),e = ReadingEssay(title:"札记",blocks:[b]),hits = ReadingTextSearch.fields(.essay(e),query:"关键词");XCTAssertEqual(hits.first?.identity,"essay:"+e.id.uuidString+":"+b.id.uuidString);XCTAssertEqual(hits.first?.source,b.text) }
    func testFootnotesFollowOccurrenceOrderNotIdentifierOrder() throws { let s = "甲[^z] 乙[^a] 再[^z]\n\n[^a]: 后出现\n[^z]: 先出现",a = try AcademicMarkup.parse(s);XCTAssertEqual(a.orderedKeys(),["z","a"]);let r = try EditorFootnotes.rendered(s);XCTAssertTrue(r.contains("甲[1] 乙[2] 再[1]"));XCTAssertTrue(a.runs("甲[^z]").contains("w:id=\"1\"")) }
    func testExportStructureOrderAndHeadingsReachPDF() throws { var o = ReadingExportOptions();o.showRecordTitles = false;o.blockOrder = ["note","quote","sources"];o.noteHeading = "个人评论";o.quoteHeading = "史料原文";let r = ReadingRecord(kind:.excerpt,quote:"引文",note:"理解"),snap = ReadingExportSnapshot(title:"汇编",records:[r],options:o),doc = try ReadingRecordExport.rich(snap,assets:try folder());let text = try doc.pdf().string ?? "";XCTAssertTrue(text.contains("个人评论"));XCTAssertTrue(text.range(of:"理解")!.lowerBound<text.range(of:"引文")!.lowerBound) }
    func testOldExportPreferencesDecodeAndNewFieldsRoundTrip() throws { let o = try JSONDecoder().decode(ReadingExportOptions.self,from:Data(#"{"fontName":"Songti SC","fontSize":12,"includeQuote":true,"includeNote":true,"includeSources":true}"#.utf8));XCTAssertEqual(o.structuralOrder,["quote","note","sources"]);var n = o;n.quoteHeading = "原始史料";n.blockOrder = ["note","sources","quote"];XCTAssertEqual(try JSONDecoder().decode(ReadingExportOptions.self,from:JSONEncoder().encode(n)),n) }
    @MainActor func testMarkedCompositionBlocksSaveWithoutChangingFile() throws { let root = try folder(),file = root.appendingPathComponent("输入.md");try "原文".write(to:file,atomically:true,encoding:.utf8);let n = try MarkdownNote.open(file,storage:root),v = ComposingTextView();n.textView = v;v.string = "原文";v.setMarkedText("zhong",selectedRange:NSRange(location:5,length:0),replacementRange:NSRange(location:2,length:0));n.toggleReadOnly();XCTAssertFalse(n.readOnly);XCTAssertFalse(n.save());XCTAssertEqual(try String(contentsOf:file,encoding:.utf8),"原文");XCTAssertEqual(n.text,"原文");v.unmarkText() }
    func testContextLoaderRejectsMissingOriginal() { XCTAssertThrowsError(try ReadingContextLoader.load(SourceRef(path:"/no/such.pdf",fileName:"原文",page:0),wholePage:false)) }
    @MainActor func testContextSnapshotDoesNotModifySourcePDF() throws { let root = try folder(),file = root.appendingPathComponent("原文.pdf");let data = try XCTUnwrap(SignaturePositionTests().document(pages:1).dataRepresentation());try data.write(to:file);let preview = try ReadingContextLoader.load(SourceRef(path:file.path,fileName:"原文",page:0),wholePage:true);XCTAssertTrue(preview.png.count>0);XCTAssertEqual(try Data(contentsOf:file),data) }
}
